// src\app\api\upload_profile_picture\route.js
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import formidable from 'formidable';

// Prevent Next.js from parsing the body
export const config = { api: { bodyParser: false } };

const s3 = new S3Client({
  region: 'auto',
  endpoint: process.env.R2_ENDPOINT,
  credentials: {
    accessKeyId: process.env.R2_ACCESS_KEY_ID,
    secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,
  },
});

export default async function handler(req, res) {
  const form = new formidable.IncomingForm();
  form.parse(req, async (err, fields, files) => {
    if (err) return res.status(500).json({ error: 'Form parsing failed' });
    try {
      const gymId = fields.gym_id; // Get gymID from form
      const file = files.profilePicture;

      if (!gymId || !file) {
        return res.status(400).json({ error: 'Missing gym_id or file' });
      }

      // Read file buffer
      const fs = require('fs');
      const data = fs.readFileSync(file.filepath);

      // Upload to R2
      const putParams = {
        Bucket: process.env.R2_BUCKET,
        Key: `${gymId}`, // Use gymId as file name/key
        Body: data,
        ContentType: file.mimetype,
      };

      await s3.send(new PutObjectCommand(putParams));
      // Optionally: Save URL/path to your Neon database for later lookup

      res.status(200).json({ success: true, key: gymId });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  });
}
